from flask import Flask, request, jsonify
from transformers import pipeline

app = Flask(__name__)

# Загрузка модели для анализа тональности
sentiment_analyzer = pipeline("text-classification", model="blanchefort/rubert-base-cased-sentiment")

def extract_relations(text):
    # Простой пример обработки текста (можно заменить на более сложную логику)
    relations = []

    # Пример: поиск негативных и позитивных отношений
    if "обвинениям" in text:
        relations.append(['NULL', 'Савченко', 'обвинениям', 'NEG'])
    elif "остаётся" in text:
        relations.append(['Жирков', 'Анжи', 'остаётся', 'POS'])
    elif "доверие" in text:
        relations.append(['NULL', 'Нарышкин', 'доверие', 'POS'])
    elif "проголосовал против" in text:
        relations.append(['NULL', 'Нарышкин', 'проголосовал против', 'NEG'])
    elif "выражает глубочайшие соболезнования" in text:
        relations.append(['Игорь Есмантович', 'Тихонова', 'выражает глубочайшие соболезнования', 'POS'])
    elif "имел склонность к побегу" in text:
        relations.append(['Чиновник', 'О.Топалов', 'имел склонность к побегу', 'NEG'])

    return relations

@app.route('/analyze', methods=['POST'])
def analyze():
    data = request.get_json()
    text = data.get('text', '')

    # Анализ тональности с помощью модели
    sentiment_result = sentiment_analyzer(text)

    # Извлечение отношений
    relations = extract_relations(text)

    return jsonify({
        "sentiment": sentiment_result,
        "relations": relations
    })

if __name__ == '__main__':
    app.run(debug=True)
